      "qualname": "funcy/_inspect.py::get_spec",
      "source": "def get_spec(func, _cache={}):
    func = getattr(func, '__original__', None) or unwrap(func)
    try:
        cached_result = _cache[func]
        return cached_result
    except (KeyError, TypeError):
        pass

    mod = getattr(func, '__module__', None)
    if mod in STD_MODULES or mod in ARGS and func.__name__ in ARGS[mod]:
        _spec = ARGS[mod].get(func.__name__, '*')
        required_part, _, optional_part = _spec.partition('-')
        req_names_list = re.findall(r'\w+|\*', required_part)
        max_n_val = len(req_names_list) + len(optional_part)
        req_n_val = len(req_names_list)
        spec_obj = Spec(max_n=max_n_val, names=set(), req_n=req_n_val, req_names=set(req_names_list), varkw=False)
        _cache[func] = spec_obj
        return spec_obj
    elif isinstance(func, type):
        objclass = getattr(func.__init__, '__objclass__', None)
        if objclass and objclass is not func:
            return get_spec(objclass)
        init_spec = get_spec(func.__init__)
        self_set = {func.__init__.__code__.co_varnames[0]}
        new_max_n = init_spec.max_n - 1
        new_names = init_spec.names - self_set
        new_req_n = init_spec.req_n - 1
        new_req_names = init_spec.req_names - self_set
        return init_spec._replace(max_n=new_max_n, names=new_names,
                             req_n=new_req_n, req_names=new_req_names)
    elif hasattr(func, '__code__'):
        return _code_to_spec(func)
    else:
        try:
            sig = signature(func)
        except (ValueError, TypeError):
            qual_name = getattr(func, '__qualname__', None)
            name_attr = getattr(func, '__name__', func)
            display_name = qual_name if qual_name is not None else name_attr
            raise ValueError('Unable to introspect %s() arguments' % display_name)
        else:
            spec_obj = _sig_to_spec(sig)
            _cache[func] = spec_obj
            return spec_obj"
    },
    {
      "qualname": "funcy/_inspect.py::_code_to_spec",
      "source": "def _code_to_spec(func):
    code = func.__code__

    defaults = getattr(func, '__defaults__', None)
    if isinstance(defaults, tuple):
        defaults_n = len(defaults)
    else:
        defaults_n = 0

    kwdefaults = getattr(func, '__kwdefaults__', None)
    if not isinstance(kwdefaults, dict):
        kwdefaults = {}

    posonly_n = getattr(code, 'co_posonlyargcount', 0)

    varnames = code.co_varnames
    pos_n = code.co_argcount
    n_val = pos_n + code.co_kwonlyargcount
    names_set = set(varnames[posonly_n:n_val])
    req_n_val = n_val - defaults_n - len(kwdefaults)
    pre_defaults_slice = varnames[posonly_n:pos_n - defaults_n]
    kwonly_slice = varnames[pos_n:n_val]
    combined_names = pre_defaults_slice + kwonly_slice
    req_names_set = set(combined_names) - set(kwdefaults)
    varkw_flag = bool(code.co_flags & CO_VARKEYWORDS)
    if code.co_flags & CO_VARARGS:
        max_n_val = n_val + 1
    else:
        max_n_val = n_val
    return Spec(max_n=max_n_val, names=names_set, req_n=req_n_val, req_names=req_names_set, varkw=varkw_flag)"
    },
    {
      "qualname": "funcy/_inspect.py::_sig_to_spec",
      "source": "def _sig_to_spec(sig):
    max_n_val = 0
    names_set = set()
    req_n_val = 0
    req_names_set = set()
    varkw_flag = False
    for name, param in sig.parameters.items():
        max_n_val += 1
        if param.kind == param.VAR_KEYWORD:
            max_n_val -= 1
            varkw_flag = True
        elif param.kind == param.VAR_POSITIONAL:
            req_n_val += 1
        elif param.kind == param.POSITIONAL_ONLY:
            if param.default is param.empty:
                req_n_val += 1
        else:
            names_set.add(name)
            if param.default is param.empty:
                req_n_val += 1
                req_names_set.add(name)
    return Spec(max_n=max_n_val, names=names_set, req_n=req_n_val, req_names=req_names_set, varkw=varkw_flag)"
    },
