    {
      "qualname": "funcy/calc.py::_memory_decorator",
      "source": "def _memory_decorator(memory, key_func):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if key_func is not None:
                key = key_func(*args, **kwargs)
            else:
                if kwargs:
                    key = args + tuple(sorted(kwargs.items()))
                else:
                    key = args
            try:
                return memory[key]
            except KeyError:
                try:
                    value = func(*args, **kwargs)
                    memory[key] = value
                    return value
                except SkipMemory as e:
                    if e.args:
                        return e.args[0]
                    else:
                        return None

        def invalidate(*args, **kwargs):
            if key_func is not None:
                key = key_func(*args, **kwargs)
            else:
                if kwargs:
                    key = args + tuple(sorted(kwargs.items()))
                else:
                    key = args
            memory.pop(key, None)
        wrapper.invalidate = invalidate

        def invalidate_all():
            memory.clear()
        wrapper.invalidate_all = invalidate_all

        wrapper.memory = memory
        return wrapper
    return decorator"
    },
