      "qualname": "funcy/colls.py::_factory",
      "source": "def _factory(coll, mapper=None):
    coll_type = type(coll)
    if isinstance(coll, defaultdict):
        item_factory = None
        if mapper and coll.default_factory:
            item_factory = compose(mapper, coll.default_factory)
        else:
            item_factory = coll.default_factory
        return partial(defaultdict, item_factory)
    elif isinstance(coll, Iterator):
        return iter
    elif isinstance(coll, (bytes, str)):
        return coll_type().join
    elif coll_type in FACTORY_REPLACE:
        return FACTORY_REPLACE[coll_type]
    else:
        return coll_type"
