      "qualname": "funcy/colls.py::join",
      "source": "def join(colls):
    """Joins several collections of same type into one."""
    colls_iterable, colls_copy = tee(colls)
    it = iter(colls_copy)
    try:
        dest = next(it)
    except StopIteration:
        return None
    cls = dest.__class__

    if isinstance(dest, (bytes, str)):
        return ''.join(colls_iterable)
    elif isinstance(dest, Mapping):
        result = dest.copy()
        for d in it:
            result.update(d)
        return result
    elif isinstance(dest, Set):
        return dest.union(*it)
    elif isinstance(dest, (Iterator, range)):
        return chain.from_iterable(colls_iterable)
    elif isinstance(dest, Iterable):
        return cls(chain.from_iterable(colls_iterable))
    else:
        raise TypeError("Don't know how to join %s" % cls.__name__)"
    },
