      "qualname": "funcy/funcmakers.py::make_func",
      "source": "def make_func(f, test=False):
    if callable(f):
        return f
    elif f is None:
        if test:
            return bool
        else:
            return lambda x: x
    elif isinstance(f, (bytes, str, _re_type)):
        if test:
            return re_tester(f)
        else:
            return re_finder(f)
    elif isinstance(f, (int, slice)):
        return itemgetter(f)
    elif isinstance(f, Mapping):
        return f.__getitem__
    elif isinstance(f, Set):
        return f.__contains__
    else:
        raise TypeError("Can't make a func from %s" % f.__class__.__name__)"
